create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('customer','driver','admin'); exception when duplicate_object then null; end $$;
do $$ begin create type public.order_status as enum ('pending','accepted','preparing','picked_up','on_the_way','delivered','cancelled'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text unique,role public.app_role not null default 'customer',created_at timestamptz not null default now());
create table if not exists public.stores(id uuid primary key default gen_random_uuid(),name text not null,category text not null,description text default '',address text default '',latitude double precision,longitude double precision,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),store_id uuid references public.stores(id) on delete cascade,name text not null,description text default '',price_dzd integer not null check(price_dzd>=0),category text not null default 'عام',is_available boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),customer_id uuid references public.profiles(id),driver_id uuid references public.profiles(id),customer_phone text not null,delivery_address text not null,latitude double precision,longitude double precision,notes text default '',items jsonb not null,total_amount integer not null check(total_amount>=0),status public.order_status not null default 'pending',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.driver_locations(driver_id uuid primary key references public.profiles(id) on delete cascade,latitude double precision not null,longitude double precision not null,updated_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.stores enable row level security; alter table public.products enable row level security; alter table public.orders enable row level security; alter table public.driver_locations enable row level security;
drop policy if exists "profiles read own" on public.profiles; create policy "profiles read own" on public.profiles for select to authenticated using(auth.uid()=id);
drop policy if exists "stores public read active" on public.stores; create policy "stores public read active" on public.stores for select to anon,authenticated using(is_active);
drop policy if exists "products public read available" on public.products; create policy "products public read available" on public.products for select to anon,authenticated using(is_available);
-- Orders require authenticated users and server-controlled profile/role provisioning before production use.
drop policy if exists "customer create own order" on public.orders; create policy "customer create own order" on public.orders for insert to authenticated with check(customer_id=auth.uid());
drop policy if exists "customer read own orders" on public.orders; create policy "customer read own orders" on public.orders for select to authenticated using(customer_id=auth.uid());
drop policy if exists "driver read assigned orders" on public.orders; create policy "driver read assigned orders" on public.orders for select to authenticated using(driver_id=auth.uid());
drop policy if exists "driver manage own location" on public.driver_locations; create policy "driver manage own location" on public.driver_locations for all to authenticated using(driver_id=auth.uid()) with check(driver_id=auth.uid());
-- Admin policies and trusted role assignment must be implemented server-side; do not trust client-editable roles.
